import{_ as t,c as e,o as r,ae as n}from"./chunks/framework.Bi6zybwU.js";const b=JSON.parse('{"title":"How to Create Ninja Charts with Ninja Tables Data","description":"How to Create Ninja Charts with Ninja Tables Data","frontmatter":{"title":"How to Create Ninja Charts with Ninja Tables Data","description":"How to Create Ninja Charts with Ninja Tables Data"},"headers":[],"relativePath":"guide/ninja-charts/create-ninja-charts-with-ninja-tables-data.md","filePath":"guide/ninja-charts/create-ninja-charts-with-ninja-tables-data.md"}'),i={name:"guide/ninja-charts/create-ninja-charts-with-ninja-tables-data.md"};function s(o,a,c,l,h,u){return r(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="how-to-create-ninja-charts-with-ninja-tables-data" tabindex="-1">How to Create Ninja Charts with Ninja Tables Data <a class="header-anchor" href="#how-to-create-ninja-charts-with-ninja-tables-data" aria-label="Permalink to &quot;How to Create Ninja Charts with Ninja Tables Data&quot;">​</a></h1><p>If you have a data table created with Ninja Tables ready to go, you can turn those table data into a chart using Ninja Charts! Since it&#39;s a free integration, you only need the 2 plugins in your dashboard to create a chart with table data. We&#39;ll show you how.</p><h2 id="create-charts-with-ninja-tables-data" tabindex="-1">Create Charts with Ninja Tables Data <a class="header-anchor" href="#create-charts-with-ninja-tables-data" aria-label="Permalink to &quot;Create Charts with Ninja Tables Data&quot;">​</a></h2><p>As usual, start by selecting chart renderer (Charts Js or Google Charts) in Ninja Charts. Then if you have a prefered chart type, select it from the 10+ options. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Create-a-chart-01-1024x580.webp" alt="Create a chart"></p><h3 id="select-ninja-tables-as-chart-data-source" tabindex="-1">Select Ninja Tables as Chart Data Source <a class="header-anchor" href="#select-ninja-tables-as-chart-data-source" aria-label="Permalink to &quot;Select Ninja Tables as Chart Data Source&quot;">​</a></h3><p>Just like the usual data source layout, you can see 3 data source options to create your chart.</p><ul><li>Manual Input: Users can input their own data manually</li><li>Ninja Tables: Create chart using a table</li><li>Fluent Forms: Create chart using form entries We’ll select Ninja Tables as the chart data source. <img src="https://ninjatables.com/wp-content/uploads/2025/08/Select-Ninja-Tables-as-chart-data-source-1024x400.webp" alt="Select Ninja Tables as chart data source"> Once you select the source, you can select the table data you want to turn into a chart. Pick a table and populate your chart. <img src="https://ninjatables.com/wp-content/uploads/2025/08/Select-table-data-for-chart-1024x476.webp" alt="Select table data for chart"> You can now hit &quot;Next&quot; and customize your chart as you want. <strong>Tip</strong>: Tables with text input are not suitable for charts like pie chart or radar. For Ninja Charts to correctly populate table entries, you need to pick the correct table and the correct chart type. Duplicate text type or invalid data type cannot create a chart.</li></ul>',7)])])}const p=t(i,[["render",s]]);export{b as __pageData,p as default};
